29: #include <turbojpeg.h>
30: #include <stdlib.h>
31: #include <stdint.h>
32: #include <string.h>
33:
34:
35: extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
36: {
37:   tjhandle handle = NULL;
38:   unsigned char *dstBufs[1] = { NULL };
39:   unsigned long dstSizes[1] = { 0 }, maxBufSize;
40:   int width = 0, height = 0, jpegSubsamp, jpegColorspace, i;
41:   tjtransform transforms[1];
42: #if defined(__has_feature) && __has_feature(memory_sanitizer)
43:   char env[18] = "JSIMD_FORCENONE=1";
44:
45:   /* The libjpeg-turbo SIMD extensions produce false positives with
46:      MemorySanitizer. */
47:   putenv(env);
48: #endif
49:
50:   if ((handle = tjInitTransform()) == NULL)
51:     goto bailout;
52:
53:   /* We ignore the return value of tjDecompressHeader3(), because some JPEG
54:      images may have unusual subsampling configurations that the TurboJPEG API
55:      cannot identify but can still transform. */
56:   tjDecompressHeader3(handle, data, size, &width, &height, &jpegSubsamp,
57:                       &jpegColorspace);
58:
59:   /* Ignore 0-pixel images and images larger than 1 Megapixel.  Casting width
60:      to (uint64_t) prevents integer overflow if width * height > INT_MAX. */
61:   if (width < 1 || height < 1 || (uint64_t)width * height > 1048576)
62:     goto bailout;
63:
64:   if (jpegSubsamp < 0 || jpegSubsamp >= TJ_NUMSAMP)
65:     jpegSubsamp = TJSAMP_444;
66:
67:   memset(&transforms[0], 0, sizeof(tjtransform));
68:
69:   transforms[0].op = TJXOP_NONE;
70:   transforms[0].options = TJXOPT_PROGRESSIVE | TJXOPT_COPYNONE;
71:   dstBufs[0] = (unsigned char *)malloc(tjBufSize(width, height, jpegSubsamp));
72:   if (!dstBufs[0])
73:     goto bailout;
74:
75:   maxBufSize = tjBufSize(width, height, jpegSubsamp);
76:
77:   if (tjTransform(handle, data, size, 1, dstBufs, dstSizes, transforms,
78:                   TJFLAG_LIMITSCANS | TJFLAG_NOREALLOC) == 0) {
79:     /* Touch all of the output pixels in order to catch uninitialized reads
80:        when using MemorySanitizer. */
81:     int sum = 0;
82:
83:     for (i = 0; i < dstSizes[0]; i++)
84:       sum += dstBufs[0][i];
85:
86:     /* Prevent the code above from being optimized out.  This test should
87:        never be true, but the compiler doesn't know that. */
88:     if (sum > 255 * maxBufSize)
89:       goto bailout;
90:   }
91:
92:   free(dstBufs[0]);
93:   dstBufs[0] = NULL;
94:
95:   transforms[0].r.w = (height + 1) / 2;
96:   transforms[0].r.h = (width + 1) / 2;
97:   transforms[0].op = TJXOP_TRANSPOSE;
98:   transforms[0].options = TJXOPT_GRAY | TJXOPT_CROP | TJXOPT_COPYNONE;
99:   dstBufs[0] =
100:     (unsigned char *)malloc(tjBufSize((height + 1) / 2, (width + 1) / 2,
101:                                       TJSAMP_GRAY));
102:   if (!dstBufs[0])
103:     goto bailout;
104:
105:   maxBufSize = tjBufSize((height + 1) / 2, (width + 1) / 2, TJSAMP_GRAY);
106:
107:   if (tjTransform(handle, data, size, 1, dstBufs, dstSizes, transforms,
108:                   TJFLAG_LIMITSCANS | TJFLAG_NOREALLOC) == 0) {
109:     int sum = 0;
110:
111:     for (i = 0; i < dstSizes[0]; i++)
112:       sum += dstBufs[0][i];
113:
114:     if (sum > 255 * maxBufSize)
115:       goto bailout;
116:   }
117:
118:   free(dstBufs[0]);
119:   dstBufs[0] = NULL;
120:
121:   transforms[0].op = TJXOP_ROT90;
122:   transforms[0].options = TJXOPT_TRIM;
123:   dstBufs[0] = (unsigned char *)malloc(tjBufSize(height, width, jpegSubsamp));
124:   if (!dstBufs[0])
125:     goto bailout;
126:
127:   maxBufSize = tjBufSize(height, width, jpegSubsamp);
128:
129:   if (tjTransform(handle, data, size, 1, dstBufs, dstSizes, transforms,
130:                   TJFLAG_LIMITSCANS | TJFLAG_NOREALLOC) == 0) {
131:     int sum = 0;
132:
133:     for (i = 0; i < dstSizes[0]; i++)
134:       sum += dstBufs[0][i];
135:
136:     if (sum > 255 * maxBufSize)
137:       goto bailout;
138:   }
139:
140:   free(dstBufs[0]);
141:   dstBufs[0] = NULL;
142:   dstSizes[0] = 0;
143:
144:   if (tjTransform(handle, data, size, 1, dstBufs, dstSizes, transforms,
145:                   TJFLAG_LIMITSCANS) == 0) {
146:     int sum = 0;
147:
148:     for (i = 0; i < dstSizes[0]; i++)
149:       sum += dstBufs[0][i];
150:
151:     if (sum > 255 * maxBufSize)
152:       goto bailout;
153:   }
154:
155: bailout:
156:   free(dstBufs[0]);
157:   if (handle) tjDestroy(handle);
158:   return 0;
159: }
